Implementation:
```js
function tone(freq, dur, type='sine', gain=.05, delay=0, slideTo=null){
 const ctx=ensureAudio(); if(!ctx) return;
 const t0=ctx.currentTime+delay;
 const o=ctx.createOscillator(), g=ctx.createGain();
 o.type=type; o.frequency.setValueAtTime(freq,t0);
 if(slideTo) o.frequency.exponentialRampToValueAtTime(slideTo,t0+dur);
 g.gain.setValueAtTime(0,t0); g.gain.linearRampToValueAtTime(gain,t0+.012); g.gain.exponentialRampToValueAtTime(.0001,t0+dur);
 o.connect(g).connect(ctx.destination); o.start(t0); o.stop(t0+dur+.03);
}
```
