  if (!scene) return;
  const hadBoard = !!boardGroup;
  if (hadBoard) disposeGroup(boardGroup);
  boardGroup = pieceGroup = highlightGroup = effectsGroup = null;
  pieceMeshes = new Map();
  squareMeshes = [];
  createBoard();
  syncPieces();
  paintHighlights();
