function updateClocks() {
  const timed = !!game.clocks;
  el.whiteClock.hidden = !timed;
  el.blackClock.hidden = !timed;
  if (!timed) return;
  const now = performance.now();
  for (const side of ['w', 'b']) {
    let ms = game.clocks[side];
    if (game.started && !game.over && !game.paused && state.turn === side) {
      ms -= Math.max(0, now - game.lastTick);
    }
    ms = Math.max(0, ms);
    const node = side === 'w' ? el.whiteClock : el.blackClock;
    node.textContent = formatClock(ms, ms < 20000);
    node.classList.toggle('low', ms <= 30000);
    node.classList.toggle('active-clock', game.started && !game.over && state.turn === side && !game.paused);
  }
}

function updateUI() {
  if (!el.turnValue) return;
  const status = currentStatus();
  const whiteTurn = state.turn === 'w';

  el.turnValue.textContent = whiteTurn ? 'White' : 'Black';
  el.turnIcon.textContent = whiteTurn ? '♙' : '♟';
  el.turnBox.classList.toggle('in-check', status.check);
  el.turnBox.classList.toggle('game-ended', game.over);

  el.whiteCard.classList.toggle('active', whiteTurn && !game.over);
  el.blackCard.classList.toggle('active', !whiteTurn && !game.over);

  const thinking = game.thinking;
  const checkLine = status.check ? 'In check — find safety' : '';
  let whiteLine, blackLine;
  if (game.over) {
    whiteLine = blackLine = 'Game complete';
  } else if (game.spectator) {
    whiteLine = blackLine = 'Spectator view';
  } else if (game.mode === 'computer') {
    if (thinking && state.turn !== game.playerColor) {
      whiteLine = state.turn === 'w' ? 'Thinking…' : whiteTurn ? 'Thinking…' : 'Waiting';
      blackLine = state.turn === 'b' ? 'Thinking…' : !whiteTurn ? 'Thinking…' : 'Waiting';
      whiteLine = state.turn === 'w' ? 'Thinking…' : (game.playerColor === 'w' ? checkLine || 'Your move' : 'Waiting');
      blackLine = state.turn === 'b' ? 'Thinking…' : (game.playerColor === 'b' ? checkLine || 'Your move' : 'Waiting');
    } else if (state.turn === game.playerColor) {
      if (game.playerColor === 'w') { whiteLine = checkLine || 'Your move'; blackLine = 'Waiting for you'; }
      else { blackLine = checkLine || 'Your move'; whiteLine = 'Waiting for you'; }
    } else {
      if (game.playerColor === 'w') { blackLine = checkLine || 'Rival to move'; whiteLine = 'Waiting'; }
      else { whiteLine = checkLine || 'Rival to move'; blackLine = 'Waiting'; }
    }
  } else {
    if (game.spectator) {
      whiteLine = checkLine || 'White to move';
      blackLine = checkLine || 'Black to move';
    } else {
      whiteLine = checkLine || (whiteTurn ? 'To move' : 'Waiting');
      blackLine = checkLine || (!whiteTurn ? 'To move' : 'Waiting');
    }
  }
  el.whiteSub.textContent = whiteLine;
  el.blackSub.textContent = blackLine;
  updateClocks();

  el.whiteCaptured.textContent = capturedBy.w.map(p => GLYPHS['b' + p.t]).join('');
  el.blackCaptured.textContent = capturedBy.b.map(p => GLYPHS['w' + p.t]).join('');

  if (game.mode === 'computer') {
    const playerIsWhite = game.playerColor === 'w';
    el.whiteName.textContent = playerIsWhite ? 'You' : 'The rival';
    el.blackName.textContent = playerIsWhite ? 'The rival' : 'You';
    el.whiteTag.textContent = playerIsWhite ? 'YOU' : 'RIVAL';
    el.blackTag.textContent = playerIsWhite ? 'RIVAL' : 'YOU';
  } else {
    el.whiteName.textContent = 'White pieces';
    el.blackName.textContent = 'Black pieces';
    el.whiteTag.textContent = 'PLAYER 1';
    el.blackTag.textContent = 'PLAYER 2';
  }

  const tc = TIME_CONTROLS[game.timeKey] || TIME_CONTROLS.unlimited;
  const modeLabel = game.mode === 'computer' ? 'VS COMPUTER' : 'LOCAL 1V1';
  el.modeBadge.textContent = modeLabel;
  el.modeBadge.classList.toggle('local', game.mode === 'local');
  if (game.mode === 'computer') {
    el.modeDetail.textContent = `${DIFFICULTY_LABEL[game.difficulty]} · ${STYLE_LABEL[game.style]}`;
  } else {
    el.modeDetail.textContent = `${VARIANT_LABEL[game.variant]} · ${tc.label}`;
  }

  el.modeCaption.textContent = game.mode === 'computer'
    ? 'ADAPTIVE RIVAL · OFFLINE'
    : `${VARIANT_LABEL[game.variant].toUpperCase()} · PASS & PLAY`;
  el.panelKicker.textContent = game.mode === 'computer' ? 'YOUR RIVAL AWAITS' : 'SHARE THE BOARD';
  el.panelTitle.innerHTML = game.mode === 'computer' ? 'Make your<br><em>move.</em>' : 'Two minds.<br><em>One board.</em>';
