function toggleSpectator() {
  if (game.mode !== 'local') return;
  game.spectator = !game.spectator;
  prefs.spectator = game.spectator;
  savePrefs();
  if (game.spectator) {
    pauseGameClock();
    selected = null;
    legalTargets = [];
    hintMove = null;
    paintHighlights();
    sound('click');
    notify('Spectator view — board input paused.');
  } else {
    resumeGameClock();
